const task=(object,position,anchor,text)=>({object,position,anchor,text});
const lesson=(id,title,tasks)=>({id:'move-'+id,title,tasks});
export const moveLessons=[
 lesson('in-out','1 · In / out of',[
  task('ball','in','box','Put the ball in the box.'),task('ball','out of','box','Take the ball out of the box.'),task('pen','in','pocket','Put the pen in the pocket.'),task('pen','out of','pocket','Take the pen out of the pocket.')]),
 lesson('on-under','2 · On / under',[
  task('ball','on','chair','Put the ball on the chair.'),task('ball','under','chair','Put the ball under the chair.'),task('book','on','table','Put the book on the table.'),task('book','under','table','Put the book under the table.')]),
 lesson('beside','3 · Beside',[
  task('ball','beside','box','Put the ball beside the box.'),task('pen','beside','book','Put the pen beside the book.'),task('toy car','beside','chair','Put the toy car beside the chair.')]),
 lesson('front-behind','4 · In front of / behind',[
  task('ball','in front of','chair','Put the ball in front of the chair.'),task('ball','behind','chair','Put the ball behind the chair.'),task('toy car','in front of','box','Put the toy car in front of the box.'),task('toy car','behind','box','Put the toy car behind the box.')]),
 lesson('between','5 · Between',[
  task('ball','between','two boxes','Put the ball between the two boxes.'),task('pen','between','two books','Put the pen between the two books.'),task('toy car','between','chair and table','Put the toy car between the chair and the table.')]),
 lesson('above-below','6 · Above / below',[
  task('balloon','above','table','Move the balloon above the table.'),task('balloon','below','table','Move the balloon below the table.'),task('star','above','cloud','Move the star above the cloud.'),task('star','below','cloud','Move the star below the cloud.')]),
 lesson('near-far','7 · Near / far from',[
  task('ball','near','tree','Put the ball near the tree.'),task('ball','far from','tree','Put the ball far from the tree.'),task('toy car','near','house','Put the toy car near the house.'),task('toy car','far from','house','Put the toy car far from the house.')]),
 lesson('into-out','8 · Into / out of',[
  task('toy car','into','garage','Move the toy car into the garage.'),task('toy car','out of','garage','Move the toy car out of the garage.'),task('ball','into','box','Move the ball into the box.'),task('ball','out of','box','Move the ball out of the box.')]),
 lesson('over-through','9 · Over / through',[
  task('ball','over','low wall','Move the ball over the low wall.'),task('ball','through','hoop','Move the ball through the hoop.'),task('toy car','through','tunnel','Move the toy car through the tunnel.')]),
 lesson('across-around','10 · Across / around',[
  task('toy car','across','bridge','Move the toy car across the bridge.'),task('toy car','around','tree','Move the toy car around the tree.'),task('boat','across','pond','Move the boat across the pond.')])
];
export const moveReview=lesson('two-steps','Final review · Two steps',[
 {text:'Take the ball out of the box. Put it under the chair.',steps:[{...task('ball','out of','box','Take the ball out of the box.'),extra:'chair'},task('ball','under','chair','Put it under the chair.')]},
 {text:'Put the book on the table. Put the pen beside the book.',steps:[task('book','on','table','Put the book on the table.'),{...task('pen','beside','book','Put the pen beside the book.'),carried:'book-on-table'}]},
 {text:'Move the toy car out of the garage. Put it behind the box.',steps:[{...task('toy car','out of','garage','Move the toy car out of the garage.'),movement:true,extra:'box'},task('toy car','behind','box','Put it behind the box.')]}]);
export const allMoveLessons=[...moveLessons,moveReview];
export const moveMeanings={
 ball:['বল','A ball.'],box:['বাক্স','A box.'],pen:['কলম','A pen.'],pocket:['পকেট','A pocket holds small things.'],chair:['চেয়ার','A chair.'],book:['বই','A book.'],table:['টেবিল','A table.'],'toy car':['খেলনা গাড়ি','A toy car.'],balloon:['বেলুন','A balloon.'],star:['তারা','A star.'],cloud:['মেঘ','A cloud.'],tree:['গাছ','A tree.'],house:['বাড়ি','A house.'],garage:['গ্যারেজ','A garage is a place for a car.'],'low wall':['নিচু দেয়াল','A low wall.'],hoop:['রিং','A hoop has an opening.'],tunnel:['সুড়ঙ্গ','A tunnel has a way through.'],bridge:['সেতু','A bridge crosses to the other side.'],pond:['পুকুর','A pond.'],boat:['নৌকা','A boat.'],
 in:['ভেতরে','In means inside.'],'out of':['বাইরে; ভেতর থেকে বাইরে','Out of means from inside to outside.'],on:['ওপরে ছুঁয়ে','On touches the surface.'],under:['নিচে','Under means beneath something.'],beside:['পাশে','Beside means next to something.'],'in front of':['সামনে','In front of is on the side nearer to us.'],behind:['পেছনে','Behind is on the farther side. You can still see part of the object.'],between:['মাঝখানে','Between means in the space separating two things.'],above:['ওপরে, ফাঁক রেখে','Above is higher, with a gap. It does not touch.'],below:['নিচে','Below is lower.'],near:['কাছে','Near is close. Use the close area.'],'far from':['থেকে দূরে','Far from is farther away. Use the far area.'],into:['ভেতরে প্রবেশ করা','Into means moving from outside to inside.'],over:['ওপর দিয়ে','Over means moving above and past something.'],through:['ভেতর দিয়ে','Through means moving through an opening.'],across:['এক পাশ থেকে অন্য পাশে','Across means moving from one side to the other.'],around:['চারদিকে ঘুরে','Around means following a route round something.']
};
const anchorWords=a=>({'two boxes':['box'],'two books':['book'],'chair and table':['chair','table']})[a]||[a];
export function moveVocabulary(l){return [...new Set(l.tasks.flatMap(t=>(t.steps||[t]).flatMap(t=>[t.object,...anchorWords(t.anchor),t.position])))].map(word=>({word,meaning:moveMeanings[word][0],spoken:moveMeanings[word][1],position:!['ball','box','pen','pocket','chair','book','table','toy car','balloon','star','cloud','tree','house','garage','low wall','hoop','tunnel','bridge','pond','boat'].includes(word)}));}
export function moveTasks(l){return l.id===moveReview.id?l.tasks:[...l.tasks,...[0,1,2].map((i)=>({...l.tasks[i%l.tasks.length],practice:true}))];}
export function isMovement(t,l){return t.movement===true||['move-into-out','move-over-through','move-across-around'].includes(l.id);}
export function moveDescription(t){return ['into','out of','over','through','across','around'].includes(t.position)?'The '+t.object+' moved '+t.position+' the '+t.anchor+'.':'The '+t.object+' is '+t.position+' the '+t.anchor+'.';}
export function moveHint(t){const hints={in:'Put it inside the opening.', 'out of':'Start inside. Move it outside.',on:'Place it on the surface so it touches.',under:'Use the space underneath.',beside:'Place it next to the object, with a small gap.','in front of':'Use the nearer floor area in front of the object.',behind:'Use the farther floor area. Part of it stays visible.',between:'Use the middle space between both objects.',above:'Move it higher. Leave a gap above the surface.',below:'Move it to the lower area.',near:'Use the close placement area.','far from':'Use the placement area far away.',into:'Start outside. Pass through the entrance and finish inside.',over:'Go up and over the wall, then down on the other side.',through:'Pass through the opening from the start to the finish.',across:'Start at one side. Follow the route to the other side.',around:'Follow the curved route all the way around the tree.'};return hints[t.position];}
export function normalizeMove(raw){const records={};for(const l of allMoveLessons){const r=raw?.move?.[l.id];if(!r)continue;const n=moveTasks(l).length,results={};for(const [key,a]of Object.entries(r.results||{})){if(!/^\d+:\d+$/.test(key))continue;const [i,j]=key.split(':').map(Number);if(i>=n||j>=(moveTasks(l)[i].steps?.length||1))continue;results[key]={correct:a.correct===true,attempts:Number.isInteger(a.attempts)?Math.max(0,Math.min(10000,a.attempts)):0,wrong:Number.isInteger(a.wrong)?Math.max(0,Math.min(10000,a.wrong)):0,assisted:a.assisted===true,firstCorrect:typeof a.firstCorrect==='boolean'?a.firstCorrect:null,method:['drag','tap','route'].includes(a.method)?a.method:null};}
 const taskIndex=Number.isInteger(r.task)&&r.task>=0&&r.task<n?r.task:0;
 const point=p=>Array.isArray(p)&&p.length===2&&p.every(v=>Number.isFinite(v))?[Math.max(0,Math.min(600,p[0])),Math.max(0,Math.min(340,p[1]))]:null;
 records[l.id]={phase:['vocabulary','demo','task','finish'].includes(r.phase)?r.phase:'vocabulary',vocab:Number.isInteger(r.vocab)&&r.vocab>=0&&r.vocab<moveVocabulary(l).length?r.vocab:0,task:taskIndex,substep:r.substep===1&&moveTasks(l)[taskIndex].steps?1:0,results,demonstrated:Array.isArray(r.demonstrated)?r.demonstrated.filter(k=>/^\d+:\d+$/.test(k)):[],position:point(r.position),path:Array.isArray(r.path)?r.path.slice(-600).map(point).filter(Boolean):[],done:r.done===true,assisted:r.assisted===true};}
 return {move:records,moveCurrent:allMoveLessons.some(l=>l.id===raw?.moveCurrent)?raw.moveCurrent:null};}
export const moveAudioSpecs=[];const add=(text)=>moveAudioSpecs.push({key:'move:'+text,text,voice:'en-GB-SoniaNeural',rate:'-12%'});
for(const l of allMoveLessons){moveVocabulary(l).forEach(v=>{add(v.word);add(v.spoken);});for(const group of l.tasks){add(group.text);for(const t of group.steps||[group]){add(t.text);add(moveHint(t));add(moveDescription(t));}}}
['Well done!','Good job!','Watch the demonstration. Then try again.','Choose a route from start to finish.','Drag the object, or choose a placement area.','Your turn.','You practised this lesson.'].forEach(add);
